a2a:agent-card.a2a:json:
{
  "name": "TechWave Order Support Agent",
  "version": "1.0.0",
  "protocolVersion": "1.0",
  "description": "Agente de suporte de pedidos da TechWave Electronics. Consulta status de pedidos e pagamentos, abre cases no Salesforce, processa reembolsos no Stripe e notifica o time no Slack.",
  "supportedInterfaces": [
    {
      "url": "${config.agent.publicUrl}/rpc",
      "protocolBinding": "JSONRPC",
      "protocolVersion": "1.0",
      "tenant": ""
    }
  ],
  "skills": [
    {
      "id": "order-support",
      "name": "Order Support",
      "description": "Responde perguntas sobre pedidos, abre cases de suporte e processa reembolsos.",
      "tags": ["orders", "support", "refund", "salesforce", "stripe", "slack"],
      "examples": ["Qual o status do pedido TW-1001?", "Quero reembolso do pedido TW-1002 e abram um chamado."],
      "inputModes": ["text/plain"],
      "outputModes": ["text/plain"]
    }
  ],
  "capabilities": {
    "streaming": false,
    "pushNotifications": false,
    "stateTransitionHistory": false,
    "extendedAgentCard": false
  },
  "provider": {
    "organization": "TechWave Electronics (demo)",
    "url": "https://example.com"
  },
  "defaultInputModes": ["text/plain"],
  "defaultOutputModes": ["text/plain"]
}
